#!/usr/bin/env python3
# lastts.py FILE...: each file's last record timestamp (epoch), read from its tail
import json, os, sys
from datetime import datetime
def last(f):
    sz=os.path.getsize(f); 
    with open(f,'rb') as h:
        for back in (65536, 1<<20, sz):
            h.seek(max(0,sz-back)); data=h.read().decode('utf-8','replace').splitlines()
            for line in reversed(data):
                try: r=json.loads(line)
                except Exception: continue
                t=r.get('timestamp')
                if isinstance(t,str):
                    try: return datetime.fromisoformat(t.replace('Z','+00:00')).timestamp()
                    except Exception: pass
            if back>=sz: break
    return None
for f in sys.argv[1:]:
    print(f"{last(f)}\t{f}")
